const listCleanupsBreakdownByState = `-- name: ListCleanupsBreakdownByState :many
SELECT
    s.id AS state_id,
    s.name AS state_name,
    COUNT(DISTINCT e.id)::bigint AS cleanups_count,
    COALESCE(SUM(e.waste_collected_kg), 0)::bigint AS waste_kg,
    COUNT(pc.id)::bigint AS verified_attendees
FROM states s
LEFT JOIN event_instances e ON e.state_id = s.id AND (e.status = 'completed' OR e.status = 'published')
  AND e.start_time >= $1 AND e.start_time <= $2
  AND ($3::varchar IS NULL OR e.lga_id = $3)
LEFT JOIN participation_claims pc ON pc.event_id = e.id AND pc.status = 'approved'
WHERE ($4::varchar IS NULL OR s.zone_id = $4)
  AND ($5::varchar IS NULL OR s.id = $5)
GROUP BY s.id, s.name
ORDER BY cleanups_count DESC, s.name ASC
`

type ListCleanupsBreakdownByStateParams struct {
	StartTime   pgtype.Timestamptz `json:"start_time"`
	StartTime_2 pgtype.Timestamptz `json:"start_time_2"`
	LgaID       pgtype.Text        `json:"lga_id"`
	ZoneID      pgtype.Text        `json:"zone_id"`
	StateID     pgtype.Text        `json:"state_id"`
}

type ListCleanupsBreakdownByStateRow struct {
	StateID           string `json:"state_id"`
	StateName         string `json:"state_name"`
	CleanupsCount     int64  `json:"cleanups_count"`
	WasteKg           int64  `json:"waste_kg"`
	VerifiedAttendees int64  `json:"verified_attendees"`
}

func (q *Queries) ListCleanupsBreakdownByState(ctx context.Context, arg ListCleanupsBreakdownByStateParams) ([]ListCleanupsBreakdownByStateRow, error) {
	rows, err := q.db.Query(ctx, listCleanupsBreakdownByState,
		arg.StartTime,
		arg.StartTime_2,
		arg.LgaID,
		arg.ZoneID,
		arg.StateID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListCleanupsBreakdownByStateRow
	for rows.Next() {
		var i ListCleanupsBreakdownByStateRow
		if err := rows.Scan(
			&i.StateID,
			&i.StateName,
			&i.CleanupsCount,
			&i.WasteKg,
			&i.VerifiedAttendees,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

